export const SITE_PAGES: SitePage[] = [{"path":"/about","title":"About us","description":"Who builds Aloha Social, how it is funded and governed, and what the project is trying to be.","html":"<p>Aloha Social is an open-source social network you run on your own server. The server app is published under AGPL-3.0-or-later; native clients have their own licences. The project is developed in the open at <a href=\"https://github.com/AlohaSocial\">github.com/AlohaSocial</a>.</p>\n<h2 id=\"what-we-are-trying-to-be\">What we are trying to be</h2>\n<p>A social network that is good to be in. That sounds vague, so here is what it means in the code:</p>\n<ul>\n<li><strong>No scoreboard by default.</strong> Like, boost and follower counts are hidden. Less pressure, less comparison, less performing for strangers.</li>\n<li><strong>No advertising code or third-party ad tracking.</strong> Optional server integrations communicate with the remote services they are configured to use.</li>\n<li><strong>Recommendations with controls.</strong> The optional For You feed explains why posts appear; behavioral learning has a separate consent control, and account-scoped learning data is not federated.</li>\n<li><strong>Complexity stays hidden.</strong> Federation is genuinely complicated. None of that complexity is handed to the person posting.</li>\n<li><strong>Design comes first.</strong> A real phone layout, a dark mode that is the same design, full keyboard navigation, sound and haptics that are optional, and respect for the system&#39;s reduced-motion setting.</li>\n</ul>\n<h2 id=\"why-it-runs-in-your-workspace\">Why it runs in your workspace</h2>\n<p>Aloha Social runs inside the workspace you already have, not as another service to run. That choice buys three things a separate network cannot:</p>\n<ol>\n<li><strong>No new account, no new password.</strong> The login people already have — including single sign-on and two-factor authentication — is the login.</li>\n<li><strong>The data stays where the organisation&#39;s data already is.</strong> Posts live next to the files, calendar and chat, on infrastructure the organisation controls and backs up under its own rules.</li>\n<li><strong>It is part of the workspace.</strong> Posts appear in unified search, links unfurl in Talk, Text and Deck, and notifications use the in-app bell and mail digest.</li>\n</ol>\n<p>Read <a href=\"/nextcloud\">why it runs in your workspace</a> for the full list.</p>\n<h2 id=\"the-team\">The team</h2>\n<p>Aloha Social is built by a small core team together with contributors from across the fediverse community.</p>\n<h3 id=\"core-team\">Core team</h3>\n<ul>\n<li>Andy Scherzinger</li>\n<li>Anna</li>\n<li>Benedikt Schächner</li>\n<li>Frank Karlitschek</li>\n<li>Hamza</li>\n<li>Jan C. Borchardt</li>\n</ul>\n<p><a href=\"https://github.com/AlohaSocial/social/graphs/contributors\"><img src=\"https://contrib.rocks/image?repo=AlohaSocial/social&amp;max=100&amp;columns=20\" alt=\"All contributors\"></a></p>\n<p><strong>All contributors:</strong> <a href=\"https://github.com/AlohaSocial/social/graphs/contributors\">github.com/AlohaSocial/social/graphs/contributors</a></p>\n<p>There is no closed core and no proprietary cloud service. Everything the app does is in the repository: server code, web client, translations, tests and documentation.</p>\n<h2 id=\"how-the-project-works\">How the project works</h2>\n<ul>\n<li><strong>Developed in the open.</strong> Issues, pull requests and design decisions are discussed on GitHub. Large changes are specified in the repository&#39;s <code>docs/</code> directory before they are built.</li>\n<li><strong>Tested in layers.</strong> CI runs unit suites and build checks; integration and protocol interoperability jobs cover configured Nextcloud and remote-service paths.</li>\n<li><strong>Documented from the code.</strong> Upstream reference chapters on this site are generated from the repository&#39;s Markdown docs and link back to their source; the complete index is at <a href=\"/docs\">/docs</a>.</li>\n<li><strong>Federated, with clear protocol boundaries.</strong> ActivityPub connects to the Fediverse. Optional native AT Protocol hosting can connect to Bluesky when the administrator enables and configures it; the two protocols keep separate identities and data flows.</li>\n</ul>\n<h2 id=\"what-it-costs\">What it costs</h2>\n<p>The server app is free software under AGPL-3.0-or-later; the Android and Apple clients are MIT-licensed. Anyone may run, inspect, adapt and contribute to the software under the terms of its licence. A hosting provider may charge for running it.</p>\n<h2 id=\"take-part\">Take part</h2>\n<ul>\n<li><strong>Report a bug or ask for a feature</strong> — <a href=\"https://github.com/AlohaSocial/social/issues\">open an issue</a>.</li>\n<li><strong>Contribute code or translations</strong> — see the <a href=\"/docs/contributing\">contributing guide</a>.</li>\n<li><strong>Run it for your organisation</strong> — the <a href=\"/install\">installation guide</a> covers Aloha 34 to 36 with PHP 8.3 to 8.5.</li>\n<li><strong>Use the brand</strong> — logos, colours and the press boilerplate are on the <a href=\"/brand\">brand page</a>.</li>\n</ul>\n","toc":[{"id":"what-we-are-trying-to-be","text":"What we are trying to be","level":2},{"id":"why-it-runs-in-your-workspace","text":"Why it runs in your workspace","level":2},{"id":"the-team","text":"The team","level":2},{"id":"core-team","text":"Core team","level":3},{"id":"how-the-project-works","text":"How the project works","level":2},{"id":"what-it-costs","text":"What it costs","level":2},{"id":"take-part","text":"Take part","level":2}]},{"path":"/admin-responsibilities","title":"Admin Responsibilities","description":"What it means to run an Aloha Social server — ethical duties, legal obligations, and practical guidance for administrators.","html":"<p>Running an Aloha Social server means more than installing an app. You are operating a piece of the open social web — a server that connects people across the fediverse, stores their conversations, and shapes their online experience. This page outlines what that responsibility entails.</p>\n<hr>\n<h2 id=\"you-are-a-host-not-a-landlord\">1. You Are a Host, Not a Landlord</h2>\n<p>Your server is <strong>your users&#39; home</strong> on the fediverse. Treat it that way.</p>\n<ul>\n<li><strong>No advertising or third-party ad tracking.</strong> If you enable personalized recommendations, explain the feature and keep its separate behavioral-learning consent available.</li>\n<li><strong>No selling data</strong> — ever, in any form</li>\n<li><strong>Keep the chronological feed available.</strong> The optional ranked For You feed explains recommendations and has controls for feedback and learning.</li>\n<li><strong>Users own their posts</strong> — they can export, move, or delete them anytime</li>\n</ul>\n<p>If you would not want it done to your own conversations, do not do it to theirs.</p>\n<hr>\n<h2 id=\"moderation-is-not-optional\">2. Moderation Is Not Optional</h2>\n<p>A server without moderation is not a community — it is a liability.</p>\n<h3 id=\"minimum-viable-moderation\">Minimum viable moderation</h3>\n<ul>\n<li><strong>Clear, published rules</strong> before anyone signs up</li>\n<li><strong>A way to report</strong> posts and accounts (built into the app)</li>\n<li><strong>Timely response</strong> — hours, not days or weeks</li>\n<li><strong>Transparent actions</strong> — every warn/silence/suspend is logged with the moderator&#39;s name</li>\n</ul>\n<h3 id=\"the-five-actions-in-order\">The five actions, in order</h3>\n<ol>\n<li><strong>Warn</strong> — tell them there&#39;s a problem</li>\n<li><strong>Mark sensitive</strong> — future posts hidden behind a click</li>\n<li><strong>Silence</strong> — posts leave public timelines, followers still see them</li>\n<li><strong>Take down</strong> — delete one post everywhere it reached</li>\n<li><strong>Suspend</strong> — delete everything, sever follows, block future posts</li>\n</ol>\n<p><strong>Document every action.</strong> Aloha Social&#39;s audit log records it automatically — do not disable it.</p>\n<hr>\n<h2 id=\"federation-comes-with-duties\">3. Federation Comes With Duties</h2>\n<p>Your server talks to thousands of others. That makes you part of a shared infrastructure.</p>\n<h3 id=\"what-you-must-do\">What you must do</h3>\n<ul>\n<li><strong>Keep software updated</strong> — security patches within days, not months</li>\n<li><strong>Monitor delivery health</strong> — the admin dashboard shows federation lag and failures</li>\n<li><strong>Respect blocks</strong> — if another server blocks you, your posts stop arriving there</li>\n<li><strong>Forward reports</strong> — reports about remote accounts go to their server, without exposing the reporter</li>\n</ul>\n<h3 id=\"what-you-must-not-do\">What you must not do</h3>\n<ul>\n<li><strong>Harvest remote content</strong> for training, advertising, or analytics</li>\n<li><strong>Rewrite or strip</strong> ActivityPub signatures</li>\n<li><strong>Run a &quot;scraper&quot; instance</strong> that only consumes without contributing</li>\n</ul>\n<hr>\n<h2 id=\"privacy-is-a-default-not-a-feature\">4. Privacy Is a Default, Not a Feature</h2>\n<p>Aloha Social strips metadata from photos and encrypts keys at rest. Federation and enabled integrations exchange data with remote servers as part of their protocols. Your job is to explain those flows and configure the instance responsibly.</p>\n<ul>\n<li><strong>No advertising or analytics SDKs in the app.</strong> Configured integrations may contact remote services; disclose them and their data flows.</li>\n<li><strong>No logging of content</strong> — access logs yes, post contents no</li>\n<li><strong>Backups are your responsibility</strong> — encrypted, access-controlled, tested</li>\n<li><strong>Legal requests</strong> — have a process, require a warrant, notify the user if legally permitted</li>\n</ul>\n<hr>\n<h2 id=\"registration-open-approved-or-invited\">5. Registration: Open, Approved, or Invited?</h2>\n<p>Choose deliberately.</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Mode</th>\n<th>Best for</th>\n<th>Responsibility</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>Open</strong></td>\n<td>Public communities</td>\n<td>High spam/moderation load; need automated defenses</td>\n</tr>\n<tr>\n<td><strong>Approval</strong></td>\n<td>Organisations, clubs</td>\n<td>Manual review of every signup</td>\n</tr>\n<tr>\n<td><strong>Invitation</strong></td>\n<td>Teams, private groups</td>\n<td>You control who gets in</td>\n</tr>\n</tbody></table></div>\n<p><strong>Social-only accounts</strong> let people join for the social network only — no files, chat, or calendar access. Use them for public communities.</p>\n<hr>\n<h2 id=\"legal-and-compliance\">6. Legal &amp; Compliance</h2>\n<p>You are the <strong>data controller</strong> for your server&#39;s data.</p>\n<h3 id=\"at-minimum\">At minimum</h3>\n<ul>\n<li><strong>Privacy policy</strong> published and linked from signup</li>\n<li><strong>Terms of service</strong> that users accept on registration</li>\n<li><strong>Abuse contact</strong> (<code>abuse@your.domain</code>) that reaches a human</li>\n<li><strong>GDPR/DSGVO readiness</strong> — export, delete, portability work out of the box</li>\n</ul>\n<h3 id=\"recommended\">Recommended</h3>\n<ul>\n<li><strong>Jurisdiction disclosure</strong> — where is the server physically?</li>\n<li><strong>Data processing agreement</strong> if you process for others</li>\n<li><strong>Incident response plan</strong> — what happens if you&#39;re breached?</li>\n</ul>\n<hr>\n<h2 id=\"sustainability\">7. Sustainability</h2>\n<p>A server that disappears breaks trust across the fediverse.</p>\n<ul>\n<li><strong>Plan for continuity</strong> — document admin access, share credentials securely</li>\n<li><strong>Budget for hosting</strong> — don&#39;t run on a personal credit card</li>\n<li><strong>Announce changes</strong> — migrations, shutdowns, policy updates with 30+ days notice</li>\n<li><strong>Successor plan</strong> — who takes over if you can&#39;t?</li>\n</ul>\n<hr>\n<h2 id=\"the-ethical-baseline\">8. The Ethical Baseline</h2>\n<p>If you do nothing else, do these:</p>\n<ol>\n<li><strong>Publish your rules</strong> before the first signup</li>\n<li><strong>Respond to reports</strong> within 24 hours</li>\n<li><strong>Update weekly</strong> — security patches are not optional</li>\n<li><strong>Backup daily</strong> — test restores quarterly</li>\n<li><strong>No surprises</strong> — no secret logging, no hidden tracking, no data sales</li>\n</ol>\n<hr>\n<h2 id=\"quick-reference-admin-checklist\">Quick Reference: Admin Checklist</h2>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Daily</th>\n<th>Weekly</th>\n<th>Monthly</th>\n<th>Quarterly</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Check moderation queue</td>\n<td>Apply security updates</td>\n<td>Review federation health</td>\n<td>Test backup restore</td>\n</tr>\n<tr>\n<td>Scan abuse@ email</td>\n<td>Review new signups</td>\n<td>Audit admin actions</td>\n<td>Review policies</td>\n</tr>\n<tr>\n<td>Monitor disk space</td>\n<td>Check error logs</td>\n<td>Verify SSL certs</td>\n<td>Update disaster plan</td>\n</tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"further-reading\">Further Reading</h2>\n<ul>\n<li><a href=\"/install\">Installation guide</a> — getting to a federating server</li>\n<li><a href=\"/docs/admin\">Administration guide</a> — moderation, config, scale</li>\n<li><a href=\"/docs/configuration\">Configuration reference</a> — every setting explained</li>\n<li><a href=\"/protect\">How Aloha protects you</a> — the user-facing safety features</li>\n<li><a href=\"/privacy\">Privacy policy</a> — what is stored, what leaves, what is stripped</li>\n<li><a href=\"/gdpr\">GDPR / DSGVO compliance</a> — legal bases, rights, and what a controller owes</li>\n</ul>\n","toc":[{"id":"you-are-a-host-not-a-landlord","text":"1. You Are a Host, Not a Landlord","level":2},{"id":"moderation-is-not-optional","text":"2. Moderation Is Not Optional","level":2},{"id":"minimum-viable-moderation","text":"Minimum viable moderation","level":3},{"id":"the-five-actions-in-order","text":"The five actions, in order","level":3},{"id":"federation-comes-with-duties","text":"3. Federation Comes With Duties","level":2},{"id":"what-you-must-do","text":"What you must do","level":3},{"id":"what-you-must-not-do","text":"What you must not do","level":3},{"id":"privacy-is-a-default-not-a-feature","text":"4. Privacy Is a Default, Not a Feature","level":2},{"id":"registration-open-approved-or-invited","text":"5. Registration: Open, Approved, or Invited?","level":2},{"id":"legal-and-compliance","text":"6. Legal & Compliance","level":2},{"id":"at-minimum","text":"At minimum","level":3},{"id":"recommended","text":"Recommended","level":3},{"id":"sustainability","text":"7. Sustainability","level":2},{"id":"the-ethical-baseline","text":"8. The Ethical Baseline","level":2},{"id":"quick-reference-admin-checklist","text":"Quick Reference: Admin Checklist","level":2},{"id":"further-reading","text":"Further Reading","level":2}]},{"path":"/cookies","title":"Cookie Policy","description":"Exactly what aloha.social stores in your browser (spoiler: one theme preference), which categories are switched off entirely, and how to withdraw at any time.","html":"<p><strong>This website sets no cookies.</strong> There is no consent banner on aloha.social because there is nothing to consent to. This page is the full accounting of what is — and is not — stored on your device, and how to remove it.</p>\n<p><em>Effective 12 October 2026.</em></p>\n<hr>\n<h2 id=\"what-is-stored-on-your-device\">What is stored on your device</h2>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Category</th>\n<th>Technology</th>\n<th>What it does</th>\n<th>Consent</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>Strictly necessary</strong></td>\n<td><code>localStorage</code>, key <code>theme</code></td>\n<td>Remembers whether you chose light or dark mode. Stays on your device, is never sent anywhere.</td>\n<td>Exempt (Art. 5 (3) ePrivacy Directive — storage of information is strictly necessary for a service explicitly requested by the user)</td>\n</tr>\n<tr>\n<td><strong>Preferences</strong></td>\n<td>—</td>\n<td>Nothing beyond the theme.</td>\n<td>—</td>\n</tr>\n<tr>\n<td><strong>Statistics / analytics</strong></td>\n<td>—</td>\n<td>No analytics of any kind — no counts, no heatmaps, no A/B tests.</td>\n<td>—</td>\n</tr>\n<tr>\n<td><strong>Advertising</strong></td>\n<td>—</td>\n<td>No ads, no advertising cookies, no cross-site identifiers.</td>\n<td>—</td>\n</tr>\n<tr>\n<td><strong>Third parties</strong></td>\n<td>—</td>\n<td>No social embeds, no video embeds, no external fonts or content delivery networks. Everything is served from this domain.</td>\n<td>—</td>\n</tr>\n</tbody></table></div>\n<p>A check of the <a href=\"https://github.com/AlohaSocial/website\">source code</a> is the proof: there is no cookie library, no analytics script and no tracking pixel in the repository.</p>\n<hr>\n<h2 id=\"why-there-is-no-consent-banner\">Why there is no consent banner</h2>\n<p>Under Art. 5 (3) of the ePrivacy Directive, storing or reading information on a user&#39;s device requires consent <strong>unless</strong> the storage is strictly necessary for a service the user explicitly requested. The theme preference qualifies: it exists only because you clicked the toggle, and it does nothing else.</p>\n<p>A consent banner for a single theme flag would create a UI that processes more data (your consent choice) than the thing it is meant to protect. The honest version is this page: here is everything, here is how to remove it.</p>\n<hr>\n<h2 id=\"how-to-withdraw\">How to withdraw</h2>\n<p>Withdrawal for strictly necessary storage means removing it — you can do that at any time, in one of three ways:</p>\n<ol>\n<li><p><strong>In the browser&#39;s site settings:</strong> open the padlock icon next to the address bar → &quot;Site settings&quot; → clear data / cookies for <code>aloha.social</code>. Your theme resets to the default.</p>\n</li>\n<li><p><strong>In the developer console:</strong></p>\n<pre><code class=\"language-js\">localStorage.removeItem(&quot;theme&quot;);\n</code></pre>\n<p>then reload the page.</p>\n</li>\n<li><p><strong>Everything at once:</strong> clear the browser&#39;s history for <code>aloha.social</code> — cookies, local storage and cache are removed together.</p>\n</li>\n</ol>\n<p>There is no account, no server-side record and no cookie identifier, so removing it is complete: nothing remains on our side, because nothing about you was ever stored on our side.</p>\n<hr>\n<h2 id=\"cookies-on-other-aloha-social-servers\">Cookies on other Aloha Social servers</h2>\n<p>This page describes <strong>aloha.social</strong> only. Servers running the Aloha Social software are operated by their operators and may make their own choices; the project&#39;s software ships no tracking or advertising code. When you use such a server, its operator&#39;s privacy policy and rules apply — see the <a href=\"/servers\">server directory</a>.</p>\n<p>The project website&#39;s own data handling is described in the <a href=\"/privacy\">privacy policy</a>; your rights under the GDPR are collected on the <a href=\"/gdpr\">GDPR page</a>.</p>\n<hr>\n<h2 id=\"changes\">Changes</h2>\n<p>If this site ever adds a technology that requires consent, this page will list it <strong>before</strong> it ships, and a consent mechanism with a withdrawal path will be added. The effective date above changes with every update.</p>\n","toc":[{"id":"what-is-stored-on-your-device","text":"What is stored on your device","level":2},{"id":"why-there-is-no-consent-banner","text":"Why there is no consent banner","level":2},{"id":"how-to-withdraw","text":"How to withdraw","level":2},{"id":"cookies-on-other-aloha-social-servers","text":"Cookies on other Aloha Social servers","level":2},{"id":"changes","text":"Changes","level":2}]},{"path":"/directory","title":"Aloha Directory","description":"Discover servers, find people, and get started with curated starter packs — all from aloha.social.","html":"<p>The Aloha Directory at <strong>aloha.social</strong> is a new service that solves the three biggest gaps in getting started with Aloha Social:</p>\n<ol>\n<li><strong>Where do I sign up?</strong> — A hand-picked list of servers offering free accounts right now</li>\n<li><strong>How do I find people?</strong> — Curated search providers that replace hard-coded third-party sources</li>\n<li><strong>What do I follow first?</strong> — Community-proposed starter packs, reviewed for consent</li>\n</ol>\n<hr>\n<h2 id=\"the-problem-onboarding-without-a-server\">The problem: onboarding without a server</h2>\n<p>The fediverse asks newcomers to choose a server before they&#39;ve seen anything. Mastodon has joinmastodon.org. Bluesky has one default host. Aloha had neither — until now.</p>\n<p><strong>Three gaps stopped native apps from helping:</strong></p>\n<ol>\n<li>Public APIs said registration was closed (even when it wasn&#39;t)</li>\n<li>No registration API — only a web form</li>\n<li>Nothing told apps which servers had room</li>\n</ol>\n<hr>\n<h2 id=\"the-solution-three-signed-lists\">The solution: three signed lists</h2>\n<p>The Aloha Directory publishes three static, signed JSON lists that apps and servers download:</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>List</th>\n<th>What it does</th>\n<th>Updated</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>Servers</strong></td>\n<td>~10–50 hand-picked servers with capacity, moderation policy, languages, terms</td>\n<td>Every 15 min</td>\n</tr>\n<tr>\n<td><strong>Search providers</strong></td>\n<td>Curated Aloha servers offering account, hashtag, full-text, and trend search</td>\n<td>Every 15 min</td>\n</tr>\n<tr>\n<td><strong>Starter packs</strong></td>\n<td>Curated packs of accounts to follow, proposed by the community</td>\n<td>Daily</td>\n</tr>\n</tbody></table></div>\n<p>Every list is <strong>signed with Ed25519</strong> — clients verify the signature, not the transport. A CDN, mirror, or proxy can carry the lists without being able to change them. The directory is <strong>never in the hot path</strong>: signup, login, search, and follows go straight from app to server or server to server. If aloha.social is offline, apps and servers keep working from their last signed copy (valid for 30 days).</p>\n<hr>\n<h2 id=\"how-it-works-for-you\">How it works for you</h2>\n<h3 id=\"in-the-android-and-apple-apps\">In the Android and Apple apps</h3>\n<ol>\n<li><strong>Welcome</strong> — Tap &quot;Create account&quot; or &quot;I already have an account&quot;</li>\n<li><strong>About you (optional)</strong> — Language and interests, stays on your device</li>\n<li><strong>Suggested server</strong> — The app picks a featured server with open capacity in your language</li>\n<li><strong>Live check</strong> — App confirms the server still has room</li>\n<li><strong>Rules &amp; terms</strong> — Read and accept before continuing</li>\n<li><strong>Account details</strong> — Username, email, password, display name</li>\n<li><strong>Confirm</strong> — Email verification or approval wait</li>\n<li><strong>Log in</strong> — OAuth, seamless (no re-entering password)</li>\n<li><strong>Follow</strong> — See starter packs matching your language and interests</li>\n<li><strong>Home</strong> — Your timeline is already populated</li>\n</ol>\n<p>The app <strong>chooses the server on your device</strong> — no data about you is sent anywhere. It filters for featured servers with open signup in your language, scores by region and capacity, and picks randomly among the top five so users spread across servers naturally.</p>\n<h3 id=\"in-the-web-app\">In the web app</h3>\n<ul>\n<li>Browse servers at <strong><a href=\"/servers\">/servers</a></strong> or <strong><a href=\"/servers/list\">/servers/list</a></strong></li>\n<li>Search for people from your account — your server queries curated providers</li>\n<li>Discover starter packs on the Discover page</li>\n</ul>\n<hr>\n<h2 id=\"server-operators-how-to-get-listed\">Server operators: how to get listed</h2>\n<ol>\n<li>Enable &quot;Advertise on aloha.social&quot; in the admin settings</li>\n<li>Your server proves domain control automatically</li>\n<li>Fill in the profile: terms, privacy policy, rules, languages, jurisdiction, operator info, moderation details, account offer, search offer</li>\n<li>Two curators review — automatic checks first (HTTPS, nodeinfo, terms URLs, abuse contact, version), then human review (operator legitimacy, moderation quality, legal compliance, test signup, diversity)</li>\n<li>If approved: <strong>Listed</strong> — visible in apps, heartbeat monitored hourly</li>\n<li><strong>Featured</strong> servers (90 days listed, 98% heartbeat uptime, low approval backlog) can be the default suggestion</li>\n</ol>\n<p>Servers send hourly heartbeats with capacity, usage, search features, and health. Zero capacity or failed checks hide you from signup automatically. Curators can pause or delist with public reasons.</p>\n<hr>\n<h2 id=\"search-providers-curated-not-hard-coded\">Search providers: curated, not hard-coded</h2>\n<p>Today Aloha searches hard-coded third-party servers (mastodon.social, pixelfed.social, etc.) that never agreed to serve Aloha traffic. The Directory replaces them with <strong>curated Aloha servers</strong> that opt in.</p>\n<p><strong>What a provider offers:</strong></p>\n<ul>\n<li>Account search (handle, display name, bio, avatar, follower count)</li>\n<li>Hashtag search (tags with 7-day use counts)</li>\n<li>Post search (public posts from opted-in authors)</li>\n<li>Trends (trending tags and links)</li>\n</ul>\n<p><strong>Privacy first:</strong></p>\n<ul>\n<li>Queries go from <em>your server</em> to the provider — the provider never sees your handle, IP, or token</li>\n<li>Requests are signed with your server&#39;s directory key</li>\n<li>Providers keep query logs ≤7 days, only for abuse prevention</li>\n<li>Only opted-in content is indexed (<code>discoverable: true</code> for accounts, <code>indexable: true</code> for posts)</li>\n</ul>\n<hr>\n<h2 id=\"starter-packs-community-proposed-consent-verified\">Starter packs: community-proposed, consent-verified</h2>\n<p>Anyone with an Aloha account can propose a pack. Curators review each proposal, and <strong>every account in it is asked for consent</strong> before publication.</p>\n<p><strong>Consent is opt-in:</strong></p>\n<ol>\n<li>Account must be discoverable</li>\n<li>Account receives a notification (in-app for Aloha, DM from <code>@directory@aloha.social</code> for others)</li>\n<li>Account accepts within 14 days (or has standing &quot;allow me in curated packs&quot; preference)</li>\n</ol>\n<p>Accounts that don&#39;t answer are left out. Anyone can leave any pack at any time — the next list build drops them within 24 hours.</p>\n<p>Packs appear in:</p>\n<ul>\n<li>First-run screen during onboarding</li>\n<li>Discover page on every Aloha server</li>\n<li>Native apps before account creation</li>\n</ul>\n<hr>\n<h2 id=\"governance-and-transparency\">Governance &amp; transparency</h2>\n<ul>\n<li><strong>Phase 1:</strong> The project operates aloha.social, holds signing keys, names curators</li>\n<li><strong>Phase 2:</strong> Handover to a community foundation (charter, funding, own curators)</li>\n<li>Apps trust the <strong>root key</strong>, not the organization — no code changes needed</li>\n<li><strong>Transparency:</strong> public page with every listed server, state, review dates; quarterly transparency report; signed lists and history on GitHub</li>\n</ul>\n<hr>\n<h2 id=\"for-administrators\">For administrators</h2>\n<p>Your server can:</p>\n<ul>\n<li><strong>Opt in</strong> to the server list (one switch in admin settings)</li>\n<li><strong>Become a search provider</strong> (declare capabilities in profile)</li>\n<li><strong>Use curated search providers</strong> instead of hard-coded defaults (<code>directory_aloha_list = on</code> by default)</li>\n<li><strong>Show curated starter packs</strong> (<code>starter_packs_curated = on</code> by default)</li>\n<li><strong>Override everything</strong> — local settings always win</li>\n</ul>\n<hr>\n<h2 id=\"learn-more\">Learn more</h2>\n<ul>\n<li><a href=\"/servers\">Find a server</a> — Browse current public listings</li>\n<li><a href=\"/get-started\">Get started</a> — Your first account and post</li>\n<li><a href=\"/activitypub/native\">How Aloha Social works</a> — The hosting model</li>\n<li><a href=\"/admins\">Administration overview</a> — Running a server</li>\n</ul>\n","toc":[{"id":"the-problem-onboarding-without-a-server","text":"The problem: onboarding without a server","level":2},{"id":"the-solution-three-signed-lists","text":"The solution: three signed lists","level":2},{"id":"how-it-works-for-you","text":"How it works for you","level":2},{"id":"in-the-android-and-apple-apps","text":"In the Android and Apple apps","level":3},{"id":"in-the-web-app","text":"In the web app","level":3},{"id":"server-operators-how-to-get-listed","text":"Server operators: how to get listed","level":2},{"id":"search-providers-curated-not-hard-coded","text":"Search providers: curated, not hard-coded","level":2},{"id":"starter-packs-community-proposed-consent-verified","text":"Starter packs: community-proposed, consent-verified","level":2},{"id":"governance-and-transparency","text":"Governance & transparency","level":2},{"id":"for-administrators","text":"For administrators","level":2},{"id":"learn-more","text":"Learn more","level":2}]},{"path":"/gdpr","title":"GDPR / DSGVO compliance","description":"The GDPR rights, legal bases and controller duties in one place — how this project's website and software handle personal data under Regulation (EU) 2016/679.","html":"<p>The General Data Protection Regulation (Regulation (EU) 2016/679, &quot;GDPR&quot; in English, &quot;DSGVO&quot; in German) governs how personal data may be processed in the EU. This page collects where the obligations fall: what <strong>this website</strong> does, what <strong>the software</strong> does, and what <strong>you</strong> have to do when you operate a server.</p>\n<p>For the concrete data processed on this website, read the <a href=\"/privacy\">privacy policy</a>.</p>\n<hr>\n<h2 id=\"who-is-accountable-for-what\">Who is accountable for what</h2>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>You visit aloha.social</th>\n<th>You run your own server</th>\n<th>You use someone else&#39;s server</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>The project is the controller; processing is minimal and described in the <a href=\"/privacy\">privacy policy</a>.</td>\n<td><strong>You are the controller.</strong> The project ships the software; it never sees your data.</td>\n<td>That server&#39;s operator is the controller; their terms and rules apply.</td>\n</tr>\n<tr>\n<td>Ask via the <a href=\"/imprint\">imprint</a>.</td>\n<td>Fulfil duties with the <a href=\"/docs/admin\">admin guide</a> and <a href=\"/admin-responsibilities\">admin responsibilities</a>.</td>\n<td>Ask them directly — see <a href=\"/servers\">find a server</a>.</td>\n</tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"legal-bases-art-6-gdpr\">Legal bases (Art. 6 GDPR)</h2>\n<p>The software needs a legal basis for each processing operation. The common cases:</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Processing</th>\n<th>Legal basis</th>\n<th>Where it happens</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Storing and delivering posts</td>\n<td>Art. 6 (1) (a) — consent of the person who posts, or Art. 6 (1) (f) for public content</td>\n<td>Your server</td>\n</tr>\n<tr>\n<td>Delivering posts to other servers in the network</td>\n<td>Art. 6 (1) (f) — the server federation works only if content it accepts is delivered; every post you make is addressed to the world</td>\n<td>Your server → other servers</td>\n</tr>\n<tr>\n<td>Login and account security</td>\n<td>Art. 6 (1) (b) — performance of a contract with the account holder</td>\n<td>Your server</td>\n</tr>\n<tr>\n<td>Logs, backups, abuse prevention</td>\n<td>Art. 6 (1) (c) / (f) — legal obligation and legitimate interest in a secure service</td>\n<td>Your server, its hosting</td>\n</tr>\n<tr>\n<td>Notifications you switched on</td>\n<td>Art. 6 (1) (a) / (b) — depending on the type of notification</td>\n<td>Your server</td>\n</tr>\n<tr>\n<td>Moderation and appeals</td>\n<td>Art. 6 (1) (c) / (f) — where the law or legitimate interests require action against abuse</td>\n<td>Your server, audit log</td>\n</tr>\n<tr>\n<td>This website&#39;s server logs</td>\n<td>Art. 6 (1) (f) — operating a secure website</td>\n<td><a href=\"/imprint\">Website hosting</a></td>\n</tr>\n</tbody></table></div>\n<p><strong>Special categories (Art. 9)</strong> are not processed by design: do not post health, biometric or similar data about other people.</p>\n<hr>\n<h2 id=\"your-rights-in-practice-arts-1522\">Your rights in practice (Arts. 15–22)</h2>\n<p>The controller of the server holding your data must answer these requests. With Aloha Social they are supported by the product itself:</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Right</th>\n<th>Article</th>\n<th>How it is served</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Access</td>\n<td>Art. 15</td>\n<td>Export your data — the full export from the settings</td>\n</tr>\n<tr>\n<td>Rectification</td>\n<td>Art. 16</td>\n<td>Edit your profile and posts yourself</td>\n</tr>\n<tr>\n<td>Erasure</td>\n<td>Art. 17</td>\n<td>Account deletion that also federates deletion where technically possible</td>\n</tr>\n<tr>\n<td>Restriction</td>\n<td>Art. 18</td>\n<td>Suspended accounts are frozen rather than processed</td>\n</tr>\n<tr>\n<td>Portability</td>\n<td>Art. 20</td>\n<td>Export in machine-readable form; move to another server</td>\n</tr>\n<tr>\n<td>Objection</td>\n<td>Art. 21</td>\n<td>For legitimate-interest processing such as federation</td>\n</tr>\n<tr>\n<td>Withdraw consent</td>\n<td>Art. 7 (3)</td>\n<td>Revoke notifications and similar at any time</td>\n</tr>\n<tr>\n<td>Complaint</td>\n<td>Art. 77</td>\n<td>To your supervisory authority — no need to ask the controller first</td>\n</tr>\n</tbody></table></div>\n<p>Requests about <strong>this website</strong> go through the contact channels in the <a href=\"/imprint\">imprint</a>.</p>\n<hr>\n<h2 id=\"privacy-by-design-art-25\">Privacy by design (Art. 25)</h2>\n<p>The software implements data minimisation instead of relying on policy promises:</p>\n<ul>\n<li><strong>No advertising or third-party analytics code in the app.</strong> Federation and configured integrations exchange data with remote servers; operators should document those flows.</li>\n<li><strong>Metadata stripped.</strong> Uploads lose EXIF, GPS and camera data before they are stored; visible timestamps are rounded and photo maps are opt-in.</li>\n<li><strong>Minimal accounts.</strong> No phone number, no address book upload, birthday or gender fields.</li>\n<li><strong>Encryption at rest.</strong> Private/public account keys are encrypted with the instance secret; delivery tokens are stored hashed.</li>\n<li><strong>Hidden engagement.</strong> Like and boost counts are hidden by default.</li>\n<li><strong>Records of processing.</strong> Moderator actions are written to the audit log, supporting the Art. 30 record.</li>\n</ul>\n<p>The security reference: <a href=\"https://github.com/AlohaSocial/social/blob/master/docs/Architecture.md#security\">architecture document</a>. The product summary: <a href=\"/protect\">How Aloha protects you</a>.</p>\n<hr>\n<h2 id=\"data-processing-agreement-art-28\">Data Processing Agreement (Art. 28)</h2>\n<p>The project <strong>does not process personal data on behalf of your deployment</strong> — you install the software and run it on your infrastructure. There is no processor relationship between the project and you, so no DPA with the project is needed for the software itself.</p>\n<p>Processing by third parties on your side (hosting, mail delivery, push notifications) is your affair: each of those is a processor or a separate controller and needs its own contract or legal basis. Check the <a href=\"/docs/admin\">admin guide</a> for which services the standard configuration contacts.</p>\n<hr>\n<h2 id=\"data-protection-officer-art-37\">Data Protection Officer (Art. 37)</h2>\n<p>No Data Protection Officer is appointed for this project website; enquiries go through the <a href=\"/imprint\">imprint</a>. Whether <em>your</em> deployment needs one is your assessment — it depends on scale and the kind of processing you do. Appointing one is optional once the conditions in Art. 37 are met.</p>\n<hr>\n<h2 id=\"international-transfers-chapter-v\">International transfers (Chapter V)</h2>\n<ul>\n<li><strong>This website:</strong> processing happens with the hosting provider described in the <a href=\"/imprint\">imprint</a>; transfers outside the EU/EEA rely on the safeguards of Chapter V.</li>\n<li><strong>Your server:</strong> federation is international by nature — posts you publish are delivered to servers in other countries, each of which is an independent controller. The legal basis for delivery is your decision to publish publicly (Art. 6 (1) (a) / (f)); the receiving server becomes responsible for its own copy.</li>\n</ul>\n<hr>\n<h2 id=\"retention\">Retention</h2>\n<ul>\n<li><strong>This website:</strong> server logs as configured by the host, normally one to seven days (<a href=\"/privacy\">privacy policy</a>).</li>\n<li><strong>Your server:</strong> keep only what you need. The <a href=\"/docs/admin\">audit log</a> and backup windows are configurable; anything else is your retention schedule to write down in your Art. 30 record.</li>\n</ul>\n<hr>\n<h2 id=\"supervisory-authority-and-contact\">Supervisory authority and contact</h2>\n<ul>\n<li><strong>This website:</strong> complaint right under Art. 77 with the authority responsible for the operator named in the <a href=\"/imprint\">imprint</a> — for an operator in Aachen, the <a href=\"https://www.ldi.nrw.de/\">LDI Nordrhein-Westfalen</a>.</li>\n<li><strong>Your server:</strong> the authority of the Member State where your main establishment is — in Germany, that is the state authority where you are based.</li>\n</ul>\n<hr>\n<h2 id=\"official-sources\">Official sources</h2>\n<ul>\n<li><a href=\"https://eur-lex.europa.eu/eli/reg/2016/679/oj\">Full text of Regulation (EU) 2016/679</a></li>\n<li><a href=\"https://www.edpb.europa.eu/our-work-tools/general-guidance/guidelines-recommendations-best-practices_en\">EDPB guidelines and documents</a></li>\n</ul>\n<p><em>This page explains the regulation and the software&#39;s support for it. It is not legal advice for your specific deployment.</em></p>\n","toc":[{"id":"who-is-accountable-for-what","text":"Who is accountable for what","level":2},{"id":"legal-bases-art-6-gdpr","text":"Legal bases (Art. 6 GDPR)","level":2},{"id":"your-rights-in-practice-arts-1522","text":"Your rights in practice (Arts. 15–22)","level":2},{"id":"privacy-by-design-art-25","text":"Privacy by design (Art. 25)","level":2},{"id":"data-processing-agreement-art-28","text":"Data Processing Agreement (Art. 28)","level":2},{"id":"data-protection-officer-art-37","text":"Data Protection Officer (Art. 37)","level":2},{"id":"international-transfers-chapter-v","text":"International transfers (Chapter V)","level":2},{"id":"retention","text":"Retention","level":2},{"id":"supervisory-authority-and-contact","text":"Supervisory authority and contact","level":2},{"id":"official-sources","text":"Official sources","level":2}]},{"path":"/imprint","title":"Imprint","description":"Legal information (Impressum) about the Aloha Social project and website — operator, contact, dispute resolution, content responsibility and trademarks.","html":"<p><em>Information pursuant to § 5 DDG (formerly § 5 TMG) and § 18 (2) MStV.</em></p>\n<hr>\n<h2 id=\"provider\">Provider</h2>\n<p><strong>Aloha Social</strong> is an open-source project. This website is operated by the Aloha Social project on behalf of the community.</p>\n<p><strong>Repository:</strong> <a href=\"https://github.com/AlohaSocial\">github.com/AlohaSocial</a>\n<strong>Website:</strong> <a href=\"https://aloha.social\">aloha.social</a>\n<strong>Issue tracker:</strong> <a href=\"https://github.com/AlohaSocial/website/issues\">github.com/AlohaSocial/website/issues</a></p>\n<h3 id=\"responsible-entity\">Responsible entity</h3>\n<p><strong>Nextcloud GmbH</strong>\nSebastian-Ritter-Straße 12\n52072 Aachen\nGermany</p>\n<p><strong>Contact:</strong> <a href=\"mailto:info@nextcloud.com\">info@nextcloud.com</a>\n<strong>Managing Director:</strong> Frank Karlitschek</p>\n<hr>\n<h2 id=\"contact\">Contact</h2>\n<ul>\n<li><strong>Project enquiries and issues:</strong> <a href=\"https://github.com/AlohaSocial/website/issues\">github.com/AlohaSocial/website/issues</a></li>\n<li><strong>Legal and privacy enquiries:</strong> <a href=\"mailto:info@nextcloud.com\">info@nextcloud.com</a> (subject line &quot;Aloha Social&quot;)</li>\n</ul>\n<p>We answer requests promptly; requests under Arts. 15–22 GDPR are handled as described in the <a href=\"/privacy\">privacy policy</a>.</p>\n<hr>\n<h2 id=\"responsible-for-content\">Responsible for content</h2>\n<p><strong>Responsible for journalistic/editorial content pursuant to § 18 (2) MStV / § 55 (2) RStV:</strong> the operator named above, at the address given above.</p>\n<hr>\n<h2 id=\"registrations-and-licences\">Registrations and licences</h2>\n<ul>\n<li><strong>Commercial register entry / VAT ID:</strong> not applicable to this website — it is an informational site of a non-commercial open-source project.</li>\n<li><strong>Professional title, chambers, supervisory authority:</strong> not applicable — no regulated professional activity is exercised through this website.</li>\n</ul>\n<hr>\n<h2 id=\"dispute-resolution\">Dispute resolution</h2>\n<ul>\n<li>The project <strong>does not participate</strong> in dispute resolution proceedings before a consumer arbitration board, and there is no obligation to do so.</li>\n<li>The European Commission&#39;s online dispute resolution platform <strong>ceased operations on 20 July 2025</strong> and is therefore not linked.</li>\n<li>Please contact us directly through the channels above — that resolves the matter faster than any procedure.</li>\n</ul>\n<hr>\n<h2 id=\"software-licence\">Software licence</h2>\n<p>Aloha Social is free software: you can redistribute it and/or modify it under the terms of the GNU Affero General Public License as published by the Free Software Foundation, either version 3 of the License, or (at your option) any later version.</p>\n<p>Aloha Social is distributed in the hope that it will be useful, but WITHOUT ANY WARRANTY; without even the implied warranty of MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE. See the GNU Affero General Public License for more details.</p>\n<p>You should have received a copy of the GNU Affero General Public License along with Aloha Social. If not, see <a href=\"https://www.gnu.org/licenses/\">gnu.org/licenses</a>.</p>\n<hr>\n<h2 id=\"third-party-services\">Third-party services</h2>\n<p>This website does <strong>not</strong> use:</p>\n<ul>\n<li>Analytics or tracking services</li>\n<li>Advertising networks</li>\n<li>External content delivery networks or social media embeds</li>\n<li>Third-party fonts at runtime — webfonts are downloaded once at build time and served from this domain</li>\n</ul>\n<p>All content is served directly from this domain. Full details: <a href=\"/cookies\">cookie policy</a>.</p>\n<hr>\n<h2 id=\"data-processing\">Data processing</h2>\n<p>This website sets no cookies and runs no analytics; the only item stored on your device is your theme preference in local storage. See the <a href=\"/privacy\">privacy policy</a> for the full policy, the <a href=\"/cookies\">cookie policy</a> for the inventory, and the <a href=\"/gdpr\">GDPR page</a> for your rights.</p>\n<p>If you install Aloha Social on your own server, <strong>you are the data controller</strong> for your instance. See <a href=\"/admin-responsibilities\">Admin responsibilities</a> for your duties.</p>\n<hr>\n<h2 id=\"trademarks\">Trademarks</h2>\n<ul>\n<li><strong>Aloha Social</strong> — project name</li>\n<li><strong>Nextcloud</strong> — registered trademark of Nextcloud GmbH</li>\n<li><strong>Mastodon, Pixelfed, PeerTube, GoToSocial, Akkoma</strong> — trademarks of their respective projects</li>\n<li><strong>Bluesky, AT Protocol</strong> — trademarks of Bluesky Social PBC</li>\n<li><strong>ActivityPub</strong> — W3C Recommendation</li>\n</ul>\n<p>Trademarks are used to identify the projects concerned; no affiliation or endorsement is implied. Brand assets: <a href=\"/brand\">brand page</a>.</p>\n<hr>\n<h2 id=\"liability\">Liability</h2>\n<p>This website provides information about the Aloha Social project. The software and the information on this site are provided &quot;as is&quot; without warranty of any kind; the scope of liability is defined in the <a href=\"/terms\">terms of service</a>.</p>\n<p>External links are provided for convenience. We are not responsible for the content of external sites.</p>\n","toc":[{"id":"provider","text":"Provider","level":2},{"id":"responsible-entity","text":"Responsible entity","level":3},{"id":"contact","text":"Contact","level":2},{"id":"responsible-for-content","text":"Responsible for content","level":2},{"id":"registrations-and-licences","text":"Registrations and licences","level":2},{"id":"dispute-resolution","text":"Dispute resolution","level":2},{"id":"software-licence","text":"Software licence","level":2},{"id":"third-party-services","text":"Third-party services","level":2},{"id":"data-processing","text":"Data processing","level":2},{"id":"trademarks","text":"Trademarks","level":2},{"id":"liability","text":"Liability","level":2}]},{"path":"/nextcloud","title":"Built into your workspace","description":"How Aloha Social uses your existing workspace for accounts, files, notifications and administration.","html":"<p>Aloha Social is an <strong>app inside your workspace</strong> — using its accounts and services rather than requiring a separate social server to operate.</p>\n<hr>\n<h2 id=\"one-account-already-yours\">One account, already yours</h2>\n<p>Your Nextcloud account <strong>is</strong> your Aloha Social account.</p>\n<ul>\n<li><strong>No new signup</strong> — open the app from your app menu, you&#39;re in</li>\n<li><strong>No new password</strong> — your existing login (including SSO and 2FA) works</li>\n<li><strong>Your profile</strong> — display name, avatar come from Aloha automatically</li>\n<li><strong>Groups = teams</strong> — your Aloha groups become team accounts and lists</li>\n</ul>\n<h3 id=\"for-people-without-a-nextcloud-account\">For people without a Nextcloud account</h3>\n<p>Admins can enable <strong>social-only accounts</strong> — people sign up for Aloha Social only, with <strong>no access</strong> to files, chat, calendar, or anything else. Signup can be open, approval-required, or invite-only.</p>\n<hr>\n<h2 id=\"your-data-stays-where-your-data-already-is\">Your data stays where your data already is</h2>\n<p>Posts live next to your files, calendar, and chat — on <strong>your infrastructure</strong>, in <strong>your database</strong>, backed up by <strong>your rules</strong>.</p>\n<ul>\n<li><strong>No advertising or third-party tracking code in the app</strong> — no map or GIF service is needed; optional integrations such as Bluesky use their configured remote services</li>\n<li><strong>Photos stripped</strong> — EXIF, GPS, camera data removed before storing (no re-encoding, quality preserved)</li>\n<li><strong>Keys encrypted</strong> — account keys encrypted with your instance secret; a database dump alone can&#39;t impersonate anyone</li>\n<li><strong>Your rules</strong> — backups, retention, logging, access control follow what you already have</li>\n</ul>\n<hr>\n<h2 id=\"part-of-your-workspace-not-next-to-it\">Part of your workspace, not next to it</h2>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>In the workspace</th>\n<th>What Aloha Social does</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>Files</strong></td>\n<td>Pick photos/videos and post — no re-upload. Replies appear in file comments.</td>\n</tr>\n<tr>\n<td><strong>Talk, Text, Deck</strong></td>\n<td>Links to posts unfurl automatically.</td>\n</tr>\n<tr>\n<td><strong>Unified search</strong></td>\n<td>Posts appear alongside files and notes.</td>\n</tr>\n<tr>\n<td><strong>Notifications</strong></td>\n<td>Uses the in-app bell and mail digest you already have.</td>\n</tr>\n<tr>\n<td><strong>Translation</strong></td>\n<td>Uses your organisation&#39;s translation provider (labelled as machine).</td>\n</tr>\n<tr>\n<td><strong>Audit log</strong></td>\n<td>Moderation actions logged beside every other admin action.</td>\n</tr>\n<tr>\n<td><strong>Groups</strong></td>\n<td>A group posts as one account; group membership controls who can post; the group becomes a read list automatically.</td>\n</tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"made-for-teams-and-organisations\">Made for teams &amp; organisations</h2>\n<ul>\n<li><strong>Team accounts</strong> — an Aloha group posts as one identity; who wrote what stays internal (team + moderators only)</li>\n<li><strong>Social-only accounts</strong> — public, members, customers get Aloha Social only, nothing else</li>\n<li><strong>Serious moderation</strong> — silence, suspend, take down; all in audit log; review queue for spam &amp; first posts; domain blocks clean up retroactively; delivery dashboard</li>\n<li><strong>Performance is measured</strong> — nightly synthetic benchmarks cover 100,000-post datasets on MySQL and PostgreSQL; results include test conditions and are not production latency guarantees</li>\n</ul>\n<hr>\n<h2 id=\"still-a-real-fediverse-server\">Still a real fediverse server</h2>\n<p>Being inside Aloha doesn&#39;t make it a walled garden:</p>\n<ul>\n<li><strong>One ActivityPub identity reaches the Fediverse</strong> — exchange supported activity with Mastodon, Pixelfed, PeerTube, GoToSocial, Akkoma and other compatible servers; exact behavior depends on each peer</li>\n<li><strong>Optional native AT Protocol hosting</strong> — an administrator can enable Bluesky-compatible identities and services alongside ActivityPub; it requires public endpoints and external PLC, relay and AppView services</li>\n<li><strong>Portable</strong> — import supported follows and posts, export an archive and move accounts where both servers support migration; imported posts are copies</li>\n<li><strong>Works everywhere</strong> — the web app in any browser, plus the native apps for Android and every Apple platform</li>\n</ul>\n<hr>\n<h2 id=\"running-it\">Running it</h2>\n<p><strong>Requirements:</strong> Aloha 34–36, PHP 8.3–8.5. Install from the App Store or build from source. AGPL-3.0 licensed, developed in the open.</p>\n<ul>\n<li><strong>You run it</strong> → <a href=\"/install\">Installation guide</a></li>\n<li><strong>You use it</strong> → <a href=\"/get-started\">Get started</a></li>\n<li><strong>You want details</strong> → <a href=\"/docs/admin\">Admin guide</a> • <a href=\"https://github.com/AlohaSocial/social/blob/master/docs/Architecture.md\">Architecture</a></li>\n</ul>\n","toc":[{"id":"one-account-already-yours","text":"One account, already yours","level":2},{"id":"for-people-without-a-nextcloud-account","text":"For people without a Nextcloud account","level":3},{"id":"your-data-stays-where-your-data-already-is","text":"Your data stays where your data already is","level":2},{"id":"part-of-your-workspace-not-next-to-it","text":"Part of your workspace, not next to it","level":2},{"id":"made-for-teams-and-organisations","text":"Made for teams & organisations","level":2},{"id":"still-a-real-fediverse-server","text":"Still a real fediverse server","level":2},{"id":"running-it","text":"Running it","level":2}]},{"path":"/privacy","title":"Privacy Policy","description":"What this website logs, what it never collects, how long anything is kept, and the rights you have under the GDPR — plus what changes when you run the software yourself.","html":"<p><strong>No ads. No analytics. No profiling.</strong> This page is the full policy for aloha.social: what is processed, on what legal basis, for how long, and how to reach us. The app&#39;s data handling is described in <a href=\"/protect\">How Aloha protects you</a>.</p>\n<p><em>Effective 12 October 2026.</em></p>\n<hr>\n<h2 id=\"who-is-responsible\">Who is responsible</h2>\n<p>The <strong>controller</strong> for this website is the operator named in the <a href=\"/imprint\">imprint</a> — the Aloha Social project, acting on behalf of the community.</p>\n<ul>\n<li><strong>Contact:</strong> through the project&#39;s public issue tracker at <a href=\"https://github.com/AlohaSocial/website/issues\">github.com/AlohaSocial/website/issues</a>, or the contact details published in the <a href=\"/imprint\">imprint</a>.</li>\n<li><strong>Scope:</strong> this policy covers <strong>aloha.social</strong>, the project&#39;s own website. It does not cover servers that run the Aloha Social software — on those, the operator of that server is the controller, and this site is not involved.</li>\n</ul>\n<hr>\n<h2 id=\"what-this-website-processes\">What this website processes</h2>\n<p>aloha.social is a <strong>statically generated website</strong>. There are no accounts, no forms, no comment fields and no databases of visitors.</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>What</th>\n<th>Examples</th>\n<th>Why</th>\n<th>Legal basis</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Server logs</td>\n<td>IP address, time, requested URL, referrer, user agent</td>\n<td>Delivering the page, preventing abuse, fixing errors</td>\n<td>Art. 6 (1) (f) GDPR — legitimate interest in a working, secure website</td>\n</tr>\n<tr>\n<td>Your theme choice</td>\n<td><code>theme</code> in your browser&#39;s local storage (<code>light</code> or <code>dark</code>)</td>\n<td>Remembering your display preference</td>\n<td>Art. 6 (1) (a) in conjunction with Art. 25 (2) GDPR — storage of information on your device is limited to what is strictly necessary, so no consent is required</td>\n</tr>\n<tr>\n<td>Nothing else</td>\n<td>—</td>\n<td>—</td>\n<td>—</td>\n</tr>\n</tbody></table></div>\n<p><strong>What is never collected:</strong> no analytics, no advertising identifiers, no profiling, no fingerprints, no social media embeds, no third-party fonts, no external content delivery networks. Fonts and images are served from this domain; every claim on this site is verifiable in the <a href=\"https://github.com/AlohaSocial/website\">source code</a>.</p>\n<hr>\n<h2 id=\"cookies-and-local-storage\">Cookies and local storage</h2>\n<p>This website sets <strong>no cookies</strong>. The single item stored on your device is the theme preference in local storage, which is technically necessary and not a cookie. The full breakdown, including how to delete it, is on the <a href=\"/cookies\">cookie policy</a> page.</p>\n<hr>\n<h2 id=\"how-long-data-is-kept\">How long data is kept</h2>\n<ul>\n<li><strong>Server logs</strong> are kept only as long as the hosting configuration requires — normally between one and seven days, and deleted automatically thereafter.</li>\n<li><strong>The theme preference</strong> stays in your browser until you clear site data for this domain; it is never transmitted anywhere.</li>\n</ul>\n<hr>\n<h2 id=\"who-receives-data\">Who receives data</h2>\n<ul>\n<li><strong>The hosting provider</strong> processes the server logs on our behalf as a processor under Art. 28 GDPR, solely to operate the site.</li>\n<li><strong>No other recipients.</strong> No advertising networks, no analytics providers, no social networks, no trackers.</li>\n<li><strong>Transfers outside the EU/EEA:</strong> where the site is hosted outside the EU/EEA, transfers rely on the safeguards of Chapter V GDPR (adequacy decision or standard contractual clauses). No personal data from this website is knowingly transferred for analytics or advertising purposes.</li>\n</ul>\n<hr>\n<h2 id=\"your-rights\">Your rights</h2>\n<p>You have the following rights against the controller, free of charge:</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Right</th>\n<th>Article</th>\n<th>What it means</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Access</td>\n<td>Art. 15</td>\n<td>A copy of the data processed about you</td>\n</tr>\n<tr>\n<td>Rectification</td>\n<td>Art. 16</td>\n<td>Correction of wrong data</td>\n</tr>\n<tr>\n<td>Erasure</td>\n<td>Art. 17</td>\n<td>Deletion, where no legal retention applies</td>\n</tr>\n<tr>\n<td>Restriction</td>\n<td>Art. 18</td>\n<td>Processing limited while a dispute is resolved</td>\n</tr>\n<tr>\n<td>Portability</td>\n<td>Art. 20</td>\n<td>Data you provided, in a machine-readable format</td>\n</tr>\n<tr>\n<td>Objection</td>\n<td>Art. 21</td>\n<td>Objection to processing based on legitimate interests</td>\n</tr>\n<tr>\n<td>Withdraw consent</td>\n<td>Art. 7 (3)</td>\n<td>Withdraw a consent at any time, with effect for the future</td>\n</tr>\n<tr>\n<td>Complaint</td>\n<td>Art. 77</td>\n<td>Appeal to a supervisory authority</td>\n</tr>\n</tbody></table></div>\n<p>Because this website processes so little, most of these requests concern your browser rather than our records: clearing site data for aloha.social removes everything stored for it.</p>\n<p><strong>Automated decision-making and profiling:</strong> none. Nothing on this website evaluates you, scores you or decides anything about you.</p>\n<p><strong>Supervisory authority:</strong> you may complain to the authority responsible for the controller named in the <a href=\"/imprint\">imprint</a>. For an operator in Aachen that is the <a href=\"https://www.ldi.nrw.de/\">Landesbeauftragte für Datenschutz und Informationsfreiheit Nordrhein-Westfalen</a>.</p>\n<hr>\n<h2 id=\"if-you-run-aloha-social-yourself\">If you run Aloha Social yourself</h2>\n<p>On a server running Aloha Social, <strong>you are the controller</strong> and this website has no access to that data at all. The software is built so that your deployment can meet the same requirements:</p>\n<ul>\n<li><strong>Data minimisation by design</strong> — the app includes no advertising or third-party analytics code; federation and configured integrations send protocol data to remote services. Photos lose their EXIF, GPS and camera metadata before they are stored.</li>\n<li><strong>Security</strong> — account keys are encrypted at rest with the instance secret, delivery is signed, tokens are stored hashed (see the <a href=\"https://github.com/AlohaSocial/social/blob/master/docs/Architecture.md#security\">architecture document</a>).</li>\n<li><strong>Erasure and portability</strong> — full export, account moves, deletion that federates.</li>\n<li><strong>Records of moderation</strong> — every moderator action is written to the audit log.</li>\n</ul>\n<p>The operational duties are described in <a href=\"/admin-responsibilities\">Admin responsibilities</a>, the settings in the <a href=\"/docs/admin\">administration guide</a>, and the overview of how the software protects people in <a href=\"/protect\">How Aloha protects you</a>. The <a href=\"/gdpr\">GDPR page</a> collects the legal bases and rights in one place.</p>\n<hr>\n<h2 id=\"updates\">Updates</h2>\n<p>This policy is updated when the website or the law changes. The current version is always this page; the effective date is at the top. Material changes are announced in the project&#39;s channels.</p>\n<p>Every claim above can be checked against the <a href=\"https://github.com/AlohaSocial/website\">source code</a> — there is no hidden tracking to find.</p>\n","toc":[{"id":"who-is-responsible","text":"Who is responsible","level":2},{"id":"what-this-website-processes","text":"What this website processes","level":2},{"id":"cookies-and-local-storage","text":"Cookies and local storage","level":2},{"id":"how-long-data-is-kept","text":"How long data is kept","level":2},{"id":"who-receives-data","text":"Who receives data","level":2},{"id":"your-rights","text":"Your rights","level":2},{"id":"if-you-run-aloha-social-yourself","text":"If you run Aloha Social yourself","level":2},{"id":"updates","text":"Updates","level":2}]},{"path":"/protect","title":"How Aloha Social protects you","description":"The defaults, filters, queues and moderation tools that keep your timeline calm — and the switches that change them.","html":"<p>Aloha Social gives people controls over feeds, notifications and unwanted content. These are design goals, not guarantees about mental-health outcomes or how other people behave.</p>\n<p>The product choices described below are controls available in the app. Their effects depend on how people and server operators use them.</p>\n<h2 id=\"the-defaults-that-are-already-on\">The defaults that are already on</h2>\n<p><strong>No scoreboard by default.</strong> Like, boost and follower counts are hidden unless you turn them on. My Feed is chronological; the optional For You feed is ranked and explains why recommendations appear.</p>\n<p><strong>Calm notifications.</strong> Every new account starts with the calm policy:</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Who is writing to you</th>\n<th>On a new account</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>People you do not follow</td>\n<td>Held for review</td>\n</tr>\n<tr>\n<td>People who do not follow you</td>\n<td>Allowed</td>\n</tr>\n<tr>\n<td>Accounts under 30 days old</td>\n<td>Held for review</td>\n</tr>\n<tr>\n<td>Private mentions you did not ask for</td>\n<td>Held for review</td>\n</tr>\n<tr>\n<td>Accounts this server limited</td>\n<td>Held for review</td>\n</tr>\n</tbody></table></div>\n<p>A held notification is stored and never raised: no bell, no push, no mail, and it does not count towards a digest. The person can still write to you — their message waits in Activities, under a line that says how many people are waiting, until you accept or dismiss it. Accepting puts them on your always-allowed list; nobody is ever told they were held.</p>\n<p><strong>Quiet hours and digests.</strong> Notifications are collected and delivered at the times you choose, so the phone does not light up at three in the morning.</p>\n<p><strong>Photos lose their location.</strong> Exif, XMP, IPTC and GPS data are stripped from every image before it is stored or sent, without re-encoding it.</p>\n<p><strong>No ad or map service.</strong> The app includes no advertising or third-party analytics code and does not need an external map or GIF service. Federation and configured integrations still communicate with remote servers. The 881 built-in emoji are served from your server.</p>\n<p><strong>AI labels.</strong> A setting can hide posts that identify themselves as AI-generated; it cannot identify unlabeled content.</p>\n<h2 id=\"filtering-before-anything-reaches-you\">Filtering, before anything reaches you</h2>\n<p><strong>Filtered words</strong> apply to every timeline this app draws. A matching post is folded behind the filter&#39;s name or taken out altogether, and a filter can expire on its own. Filters are yours: they are stored on the server, visible to nobody else, and you can have as many as you like with different rules.</p>\n<p><strong>Mute a conversation</strong> from any post in a thread. Notifications for that thread stop entirely — bell, push and mail — and the thread stops appearing in Activities. The posts stay on every timeline, so you can still read what you choose to read. Unmuting restores what arrived meanwhile without ringing for it.</p>\n<p><strong>Hide a whole server.</strong> A per-user domain block takes out everything from one domain, for you, without an administrator being involved.</p>\n<p><strong>Hide somebody&#39;s boosts</strong>, or ask to be told when they post — both sit beside the bell on their profile.</p>\n<p><strong>Block and mute.</strong> Blocking severs the relationship in both directions and hides somebody everywhere. Muting hides them from your timelines and optionally your notifications, for an hour, a day, seven days, thirty, or until you lift it — and they are never told.</p>\n<h2 id=\"before-anybody-sees-it\">Before anybody sees it</h2>\n<p>Two rules hold a post back on the server side instead of publishing it:</p>\n<ul>\n<li><strong>First-post review</strong> holds the first post of an account that has published nothing yet. Administrators&#39; own posts are never held. It is off on a server where administrators created the accounts, and on where registration is open.</li>\n<li><strong>Autospam</strong> holds a post that trips a deliberately short list of rules: more than five links in a short post, or more than five mentions from an account nobody follows and that follows nobody. There is no wordlist and no score — &quot;seven links&quot; is something a moderator can agree or disagree with in a second.</li>\n</ul>\n<p><strong>A direct message is never held.</strong> Holding one would put private correspondence in front of a moderator who was not written to, for a machine&#39;s reason.</p>\n<p>A held post is stored as the request the client sent, not as a post: it is in no timeline, no profile, no outbox and no search — not even its author&#39;s. Their own copy sits in Settings, where they can take it back.</p>\n<h2 id=\"for-moderators\">For moderators</h2>\n<p>Five actions, in order of weight, all reversible except the last two:</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Action</th>\n<th>What it costs</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>Warn</strong></td>\n<td>Nothing. The account is told there is a problem.</td>\n</tr>\n<tr>\n<td><strong>Mark everything sensitive</strong></td>\n<td>Every future post is shown behind a click.</td>\n</tr>\n<tr>\n<td><strong>Silence</strong></td>\n<td>The account leaves the public and global timelines. Deliberate followers still see it.</td>\n</tr>\n<tr>\n<td><strong>Take down</strong></td>\n<td>One post is deleted, everywhere it reached.</td>\n</tr>\n<tr>\n<td><strong>Suspend</strong></td>\n<td>Everything posted here is deleted, follows go both ways, and further sends are refused.</td>\n</tr>\n</tbody></table></div>\n<p>Every action names the moderator who took it. With Aloha&#39;s audit app enabled they land in the audit log beside every other administrative action. The strike history is never rewritten by a lift.</p>\n<p>Domain blocks work the same way at the level of a server, and clean up what a blocked server already sent.</p>\n<p>The <a href=\"/docs/admin-moderating\">administration guide</a> documents moderation, and the <a href=\"/features/safety\">safety feature page</a> shows the controls as a person meets them.</p>\n<h2 id=\"under-the-hood\">Under the hood</h2>\n<p>A page of detail for the technically curious — the <a href=\"https://github.com/AlohaSocial/social/blob/master/docs/Architecture.md#security\">security section of the architecture document</a> records all of it, with the class and method names:</p>\n<ul>\n<li>every outbound delivery is signed with the sending actor&#39;s key, and inbound ones are verified against the request target, host, date and digest, with a replay window</li>\n<li>inbound deliveries are rate-limited twice — once by source address, once by verified origin — and bodies are capped at 1 MiB</li>\n<li>actor private keys are encrypted at rest with the instance secret, so a database dump alone is not enough to impersonate anybody</li>\n<li>client secrets, authorization codes and access tokens are stored hashed</li>\n<li>outbound requests refuse private, loopback and otherwise reserved addresses, and re-check on every redirect</li>\n<li>JSON-LD contexts are served from the copies shipped with the app, never fetched for signature work</li>\n<li>an attachment from another server cannot overwrite a document this server owns</li>\n</ul>\n<h2 id=\"where-to-go-next\">Where to go next</h2>\n<ul>\n<li><a href=\"/features/safety\">The safety feature page</a> — the same controls as you meet them in the app</li>\n<li><a href=\"/docs/notify-reader-controls\">Who may reach you</a> — the notification policy in detail</li>\n<li><a href=\"/privacy\">Privacy policy</a> — what is stored, what leaves the server, and why</li>\n<li><a href=\"/gdpr\">GDPR / DSGVO compliance</a> — your rights and the software&#39;s data minimisation</li>\n<li><a href=\"/rules\">Rules for using Aloha Social</a> — what is expected of people here</li>\n<li><a href=\"/wellbeing\">Well-being in Aloha</a> — the research and design behind these choices</li>\n</ul>\n","toc":[{"id":"the-defaults-that-are-already-on","text":"The defaults that are already on","level":2},{"id":"filtering-before-anything-reaches-you","text":"Filtering, before anything reaches you","level":2},{"id":"before-anybody-sees-it","text":"Before anybody sees it","level":2},{"id":"for-moderators","text":"For moderators","level":2},{"id":"under-the-hood","text":"Under the hood","level":2},{"id":"where-to-go-next","text":"Where to go next","level":2}]},{"path":"/rules","title":"Rules for using Aloha Social","description":"What is expected of people here, what is not tolerated, and how moderation works on a server running the app.","html":"<p>Aloha Social runs on many servers, and each server sets its own rules for the people it hosts. This page is the baseline: what the app assumes, what it is built to prevent, and what you can expect from the people who run your server.</p>\n<p>Your server&#39;s own rules take precedence. Before you post somewhere new, read the rules that server publishes — the <a href=\"/servers\">find a server</a> page links to them.</p>\n<h2 id=\"the-baseline\">The baseline</h2>\n<p><strong>Be a person, not a campaign.</strong> Spam, coordinated inauthentic behaviour and undisclosed automation are the fastest way to lose an account. The server holds a first post for review where registration is open, and holds posts that look like link or mention floods.</p>\n<p><strong>Do not harass people.</strong> Targeted abuse, dogpiling, unwanted sexual attention and publishing private information are reportable everywhere in the fediverse. Blocks, mutes and filters exist so people can protect themselves first and report second.</p>\n<p><strong>Do not post illegal content.</strong> Content that is illegal where the server operates is removed, and the server&#39;s operator may be obliged to act on it.</p>\n<p><strong>Respect the audience people chose.</strong> A followers-only or direct post is addressed to a particular audience. Screenshotting it into public is a betrayal of that choice, even where the software cannot prevent it.</p>\n<p><strong>Label what needs labelling.</strong> Use content warnings for spoilers and difficult material, alt text for pictures, and the AI label when a post says it was made with AI. The composer asks; the answer is never blocked, but the nudge is deliberate.</p>\n<p><strong>Nothing here is anonymous.</strong> Your posts carry your handle and your server. Reports about accounts on other servers are forwarded without exposing who reported them, but the server operator can see what is posted from their server.</p>\n<h2 id=\"what-the-software-does-about-it\">What the software does about it</h2>\n<p>The app is built so that the rules above are cheap to enforce:</p>\n<ul>\n<li><strong>Warnings, sensitive marking, silencing, take-downs and suspensions</strong> — five actions in order of weight, each recorded against the moderator who took it, four of them reversible.</li>\n<li><strong>A review queue</strong> for a first post and for posts that trip the spam rules. A direct message is never held.</li>\n<li><strong>Domain blocks</strong> that also clean up what a blocked server already sent.</li>\n<li><strong>Reports</strong> arrive from two directions — a local person reporting through a client, and a peer server reporting on behalf of one of its own users — and land in the same queue for the administrators and the delegated group.</li>\n<li><strong>Everything lands in Aloha&#39;s audit log</strong> where the audit app is enabled, next to every other administrative action.</li>\n</ul>\n<p>See <a href=\"/protect\">How Aloha Social protects you</a> for the full list, and the <a href=\"/docs/admin-moderating\">moderating chapter</a> for the exact behaviour.</p>\n<h2 id=\"what-you-can-do-for-yourself\">What you can do for yourself</h2>\n<ul>\n<li><strong>Filtered words</strong> fold or hide matching posts in every timeline, and can expire on their own.</li>\n<li><strong>Who may reach you</strong> holds messages from strangers, new accounts and unsolicited private mentions in a review queue instead of ringing the bell.</li>\n<li><strong>Mute a conversation</strong> without leaving it; <strong>hide a whole server</strong> without asking an administrator.</li>\n<li><strong>Block</strong> severs a relationship in both directions and hides somebody everywhere, and they are never told.</li>\n<li><strong>Report</strong> a post or an account. Reports about remote accounts are relayed without exposing you.</li>\n</ul>\n<h2 id=\"reporting\">Reporting</h2>\n<p>The report button on a post or a profile sends it to the moderators of your server. Say what the problem is; a sentence is enough. Where the account belongs to another server, your server forwards the report and keeps your identity off it.</p>\n<p>Moderators cannot act on what they cannot see — if a post breaks the rules of <em>their</em> server but not yours, the useful report goes to them. The <a href=\"/servers\">find a server</a> pages link to each server&#39;s own rules and contact.</p>\n<h2 id=\"for-people-running-a-server\">For people running a server</h2>\n<p>Registration can be open, approval-based or invitation-only. Social-only accounts exist so that members of the public can sign up for Aloha Social alone, with no access to files, chat or anything else. Spam rules and first-post review are per-server switches, and the moderation settings are in the administration page.</p>\n<p>The <a href=\"/docs/admin\">administration guide</a> covers all of it, and <a href=\"/install\">the installation guide</a> covers getting a server to the point where these rules matter.</p>\n<h2 id=\"changing-these-rules\">Changing these rules</h2>\n<p>This page describes the baseline the software is built around. Your server&#39;s operator may publish stricter rules and does not need permission to do so. If you run a server, publish your rules where people can find them before they sign up — the <a href=\"/servers\">find a server</a> listing gives you a place for them.</p>\n","toc":[{"id":"the-baseline","text":"The baseline","level":2},{"id":"what-the-software-does-about-it","text":"What the software does about it","level":2},{"id":"what-you-can-do-for-yourself","text":"What you can do for yourself","level":2},{"id":"reporting","text":"Reporting","level":2},{"id":"for-people-running-a-server","text":"For people running a server","level":2},{"id":"changing-these-rules","text":"Changing these rules","level":2}]},{"path":"/sitemap","title":"Sitemap","description":"Complete list of all pages on aloha.social for navigation and discovery.","html":"<p>Key public pages on this site, organised by section. The <a href=\"/docs\">documentation index</a> lists all generated chapters; the XML sitemap includes every built route.</p>\n<hr>\n<h2 id=\"getting-started\">Getting Started</h2>\n<ul>\n<li><a href=\"/\">Home</a></li>\n<li><a href=\"/get-started\">Get started</a> — Find a server, create an account, first post</li>\n<li><a href=\"/servers\">Find a server</a> — Browse public Aloha Social servers</li>\n<li><a href=\"/servers/list\">Server list</a> — Full directory with filters</li>\n<li><a href=\"/clients\">Apps &amp; downloads</a> — Web, Android and Apple clients</li>\n</ul>\n<hr>\n<h2 id=\"why-aloha-social\">Why Aloha Social</h2>\n<ul>\n<li><a href=\"/why\">Why Aloha Social</a> — 30 reasons, checked against current implementation docs</li>\n<li><a href=\"/features\">Features</a> — Complete feature tour</li>\n<li><a href=\"/server\">How it works</a> — Federation, identity, hosting model</li>\n<li><a href=\"/activitypub\">ActivityPub</a> — How federation works</li>\n<li><a href=\"/directory\">Aloha Directory</a> — Server discovery, search providers, starter packs</li>\n</ul>\n<hr>\n<h2 id=\"safety-privacy-and-well-being\">Safety, Privacy &amp; Well-being</h2>\n<ul>\n<li><a href=\"/protect\">How Aloha protects you</a> — Calm defaults, filters, moderation tools</li>\n<li><a href=\"/privacy\">Privacy policy</a> — What is stored, what leaves, your rights</li>\n<li><a href=\"/gdpr\">GDPR / DSGVO compliance</a> — Legal bases, rights, controller duties</li>\n<li><a href=\"/cookies\">Cookie policy</a> — Everything stored on your device (spoiler: one flag)</li>\n<li><a href=\"/rules\">Rules for using Aloha</a> — Community guidelines, moderation</li>\n<li><a href=\"/wellbeing\">Well-being in Aloha</a> — Research behind the design</li>\n</ul>\n<hr>\n<h2 id=\"documentation\">Documentation</h2>\n<h3 id=\"for-users\">For Users</h3>\n<ul>\n<li><a href=\"/docs/user\">User guide</a> — Account, posting, reading, settings</li>\n<li><a href=\"/docs/user-getting-an-account\">Getting an account</a></li>\n<li><a href=\"/docs/user-finding-and-following-people\">Finding &amp; following people</a></li>\n<li><a href=\"/docs/user-writing-a-post\">Writing a post</a></li>\n<li><a href=\"/docs/user-reading\">Reading timelines</a></li>\n<li><a href=\"/docs/for-you\">For You feed</a></li>\n<li><a href=\"/features/read\">Shorts</a></li>\n<li><a href=\"/docs/notify\">Who may reach you</a></li>\n<li><a href=\"/docs/user-filtering-out-words\">Filtering words</a></li>\n<li><a href=\"/docs/user-managing-your-account\">Managing your account</a></li>\n<li><a href=\"/docs/user-keyboard-shortcuts\">Keyboard shortcuts</a></li>\n<li><a href=\"/docs/moving\">Moving an account</a></li>\n<li><a href=\"/docs/mastodon\">Mastodon compatibility</a></li>\n<li><a href=\"/docs/federation\">Federation compatibility</a></li>\n<li><a href=\"/docs/integrations\">Integrations and compatibility</a></li>\n<li><a href=\"/docs/events\">Federated events</a></li>\n</ul>\n<h3 id=\"for-administrators\">For Administrators</h3>\n<ul>\n<li><a href=\"/admins\">Admin overview</a> — Short tour for server operators</li>\n<li><a href=\"/install\">Installation guide</a> — Requirements, App Store, verification</li>\n<li><a href=\"/docs/admin\">Administration guide</a> — Checks, moderation, config, scale</li>\n<li><a href=\"/docs/configuration\">Configuration reference</a> — OCC commands, config.php, env vars</li>\n<li><a href=\"/docs/maintenance\">Maintenance &amp; updates</a> — Upgrades, backups, monitoring</li>\n<li><a href=\"/docs/performance\">Performance</a> — What a page costs, what was fixed</li>\n<li><a href=\"/docs/atproto\">AT Protocol status</a> — Bluesky compatibility</li>\n<li><a href=\"/docs/atproto-live\">Bluesky live-host checks</a> — distinguish protocol responses from public indexing</li>\n</ul>\n<h3 id=\"for-developers\">For Developers</h3>\n<ul>\n<li><a href=\"/developers\">Developer hub</a> — Repositories, endpoints, source</li>\n<li><a href=\"/developers/docs/protocol\">Protocol</a> — ActivityPub, AT Protocol details</li>\n<li><a href=\"/developers/docs/federation\">Federation</a> — Server-to-server delivery</li>\n<li><a href=\"/developers/docs/api\">API reference</a> — Endpoints, auth, responses</li>\n<li><a href=\"/developers/docs/operations\">Operations</a> — Deployment, scaling, monitoring</li>\n<li><a href=\"/docs/api\">API reference</a> — the current registered API surface</li>\n<li><a href=\"/docs/architecture\">Architecture</a> — data model, services and protocol flows</li>\n<li><a href=\"/docs/frontend\">Frontend interoperability</a></li>\n<li><a href=\"/docs/evaluation\">For You evaluation</a></li>\n<li><a href=\"/docs/releasing\">Release guide</a></li>\n</ul>\n<hr>\n<h2 id=\"project-and-community\">Project &amp; Community</h2>\n<ul>\n<li><a href=\"/about\">About us</a> — Who builds it, how it works, contributors</li>\n<li><a href=\"/nextcloud\">Built into your workspace</a> — Integration benefits</li>\n<li><a href=\"/admin-responsibilities\">Admin responsibilities</a> — Ethical duties for server operators</li>\n<li><a href=\"/docs/contributing\">Contributing</a> — Code style, PRs, tests, releases</li>\n<li><a href=\"/brand\">Brand assets</a> — Logos, colours, press kit</li>\n</ul>\n<hr>\n<h2 id=\"legal-and-technical\">Legal &amp; Technical</h2>\n<ul>\n<li><a href=\"/imprint\">Imprint</a> — Operator, contact, dispute resolution</li>\n<li><a href=\"/terms\">Terms of Service</a> — Acceptable use, liability, governing law</li>\n<li><a href=\"/sitemap.xml\">Sitemap (XML)</a> — Machine-readable sitemap</li>\n<li><a href=\"/robots.txt\">Robots.txt</a> — Crawler instructions</li>\n</ul>\n<hr>\n<p><em>This page lists every public page at the time of the last build.</em></p>\n","toc":[{"id":"getting-started","text":"Getting Started","level":2},{"id":"why-aloha-social","text":"Why Aloha Social","level":2},{"id":"safety-privacy-and-well-being","text":"Safety, Privacy & Well-being","level":2},{"id":"documentation","text":"Documentation","level":2},{"id":"for-users","text":"For Users","level":3},{"id":"for-administrators","text":"For Administrators","level":3},{"id":"for-developers","text":"For Developers","level":3},{"id":"project-and-community","text":"Project & Community","level":2},{"id":"legal-and-technical","text":"Legal & Technical","level":2}]},{"path":"/terms","title":"Terms of Service","description":"The terms on which you may use this website and the Aloha Social software — acceptable use, intellectual property, availability, liability and governing law.","html":"<p>These terms govern your use of <strong>aloha.social</strong>, the project&#39;s website, and your use of the Aloha Social software that you download from it.</p>\n<p><em>Effective 12 October 2026.</em></p>\n<hr>\n<h2 id=\"scope\">1. Scope</h2>\n<p>The website aloha.social is an informational website operated by the project described in the <a href=\"/imprint\">imprint</a>. It provides documentation, downloads and pointers to community-run servers. The software &quot;Aloha Social&quot; is separate and covered in section 6.</p>\n<p>By using this website you accept these terms. If you do not accept them, please do not use the site.</p>\n<hr>\n<h2 id=\"accounts-on-this-website\">2. Accounts on this website</h2>\n<p>This website has <strong>no registration, no login and no user accounts</strong>. If someone contacts you claiming to represent &quot;Aloha Social&quot; through an account on a chat platform or elsewhere, verify through the official <a href=\"https://github.com/AlohaSocial\">GitHub organisation</a> — we do not operate accounts for support anywhere else.</p>\n<hr>\n<h2 id=\"acceptable-use\">3. Acceptable use</h2>\n<p>You may use the website for lawful personal and commercial research, linking, quoting and mirroring within the limits of these terms. You must not:</p>\n<ul>\n<li><strong>Attack the site</strong> — no scraping beyond the intent of <a href=\"/robots.txt\">robots.txt</a>, no flooding, no attempt to probe, bypass or disrupt security, no automated access that degrades the service for others.</li>\n<li><strong>Malware</strong> — no uploading, linking to or distributing malware through the site&#39;s services.</li>\n<li><strong>Impersonation</strong> — no presenting yourself as the project, its operators or its maintainers.</li>\n<li><strong>Unlawful content</strong> — no use of the site in violation of applicable law, including copyright and privacy law.</li>\n<li><strong>Circumvention</strong> — no interference with the technical measures of the site.</li>\n</ul>\n<hr>\n<h2 id=\"intellectual-property\">4. Intellectual property</h2>\n<ul>\n<li><strong>Source code:</strong> licensed under the <a href=\"https://github.com/AlohaSocial/website/blob/main/LICENSE\">AGPL-3.0-or-later</a> licence. The licence text governs; these terms add no restriction to it.</li>\n<li><strong>Documentation and texts</strong> on this website may be quoted with attribution; for full reuse, check the repository for licence notes on individual documents.</li>\n<li><strong>Name and logos</strong> are project identifiers. Using them to truthfully refer to the project is fine; using them to suggest endorsement or an official affiliation is not. See the <a href=\"/brand\">brand page</a> and the <a href=\"/imprint\">trademark notes in the imprint</a>.</li>\n<li><strong>Third-party content</strong> on this site — screenshots of clients, links to other projects — remains the property of its respective owners and is used for identification under the applicable exceptions of copyright law.</li>\n</ul>\n<hr>\n<h2 id=\"availability-and-content\">5. Availability and content</h2>\n<ul>\n<li><strong>No uptime promise.</strong> The website is provided &quot;as is&quot; and &quot;as available&quot;. Maintenance, force majeure or hosting problems may interrupt it at any time.</li>\n<li><strong>No professional advice.</strong> Documentation describes the software to the best of the maintainers&#39; knowledge, but is no warranty of completeness, correctness or fitness for a particular purpose.</li>\n<li><strong>External links.</strong> The site links to servers, apps and projects the project does not control. Their content is their responsibility; a link is no endorsement of everything on the target.</li>\n</ul>\n<hr>\n<h2 id=\"the-aloha-social-software\">6. The Aloha Social software</h2>\n<p>The software is <strong>free and open source</strong> under the AGPL-3.0-or-later licence, with separate attribution for bundled components as listed in the repository. The licence — not these terms — governs your rights to use, modify and distribute the software.</p>\n<p>When you install the software, a third relationship begins: between <strong>you and the operator of the server</strong> (or yourself, if you are the operator). That relationship is governed by the server&#39;s rules (<a href=\"/rules\">community guidelines</a>), its administration policies (<a href=\"/admin-responsibilities\">admin responsibilities</a>) and applicable law. This website does not operate servers for end users.</p>\n<hr>\n<h2 id=\"liability\">7. Liability</h2>\n<p>To the extent permitted by German law:</p>\n<ul>\n<li>The project is liable <strong>without limitation</strong> for intent and gross negligence, for injury to life, body or health, and under the Product Liability Act.</li>\n<li>For slight negligence, liability is limited to breach of a fundamental obligation — the contract&#39;s purpose is endangered — and to foreseeable, typical damage.</li>\n<li>The same limits apply to the project&#39;s contributors and volunteers in their voluntary capacity.</li>\n<li>The foregoing does not affect mandatory statutory liability.</li>\n</ul>\n<hr>\n<h2 id=\"changes\">8. Changes</h2>\n<p>These terms may be updated when the site or the law changes. The current version is always this page, with its effective date at the top. Continued use after a change means you accept the updated terms.</p>\n<hr>\n<h2 id=\"governing-law-and-dispute-resolution\">9. Governing law and dispute resolution</h2>\n<ul>\n<li><strong>Governing law:</strong> the substantive law of the Federal Republic of Germany, excluding its conflict-of-law rules and the UN Convention on Contracts for the International Sale of Goods. Mandatory consumer protections of your home country remain unaffected.</li>\n<li><strong>Dispute resolution:</strong> the project does <strong>not</strong> participate in dispute resolution proceedings before a consumer arbitration board. The European online dispute resolution platform ceased operations on 20 July 2025. Please contact the project directly through the <a href=\"/imprint\">imprint</a> — most disagreements are resolved that way.</li>\n<li><strong>Place of jurisdiction:</strong> for merchants, public legal entities or special funds under public law, Aachen, Germany.</li>\n</ul>\n<hr>\n<h2 id=\"contact\">10. Contact</h2>\n<p>Questions about these terms go through the channels in the <a href=\"/imprint\">imprint</a>.</p>\n","toc":[{"id":"scope","text":"1. Scope","level":2},{"id":"accounts-on-this-website","text":"2. Accounts on this website","level":2},{"id":"acceptable-use","text":"3. Acceptable use","level":2},{"id":"intellectual-property","text":"4. Intellectual property","level":2},{"id":"availability-and-content","text":"5. Availability and content","level":2},{"id":"the-aloha-social-software","text":"6. The Aloha Social software","level":2},{"id":"liability","text":"7. Liability","level":2},{"id":"changes","text":"8. Changes","level":2},{"id":"governing-law-and-dispute-resolution","text":"9. Governing law and dispute resolution","level":2},{"id":"contact","text":"10. Contact","level":2}]},{"path":"/wellbeing","title":"Well-being in Aloha","description":"How Aloha Social is designed to protect your mental health and amplify positive experiences.","html":"<p>Aloha Social is designed to give people more control over what they see and when they are interrupted. These choices express the project&#39;s priorities; they are not a promise of a particular mental-health outcome.</p>\n<h2 id=\"no-engagement-scoreboard\">No engagement scoreboard</h2>\n<p>By default, you don&#39;t see like counts, boost counts, or follower numbers — on your posts or anyone else&#39;s. This simple change removes the constant pressure to perform for strangers. You post because you want to share, not because you&#39;re chasing a number.</p>\n<p>The setting changes how the interface presents activity; it does not remove engagement data from remote services or guarantee how other people respond.</p>\n<h2 id=\"calm-notifications-by-default\">Calm notifications by default</h2>\n<p>New accounts start with a calm notification policy:</p>\n<ul>\n<li>Messages from people you don&#39;t follow are held for review</li>\n<li>Messages from accounts under 30 days old are held for review</li>\n<li>Private mentions you didn&#39;t ask for are held for review</li>\n<li>Accounts your server has limited are held for review</li>\n</ul>\n<p>Held notifications don&#39;t ring, don&#39;t push, don&#39;t email — they simply wait in an &quot;Activities&quot; section until you choose to look. This means your phone doesn&#39;t interrupt your dinner, your sleep, or your focus.</p>\n<p>You decide which notifications to hold, digest or receive. A held notification waits in Activities instead of raising a bell, push or email alert.</p>\n<h2 id=\"quiet-hours-and-digests\">Quiet hours and digests</h2>\n<p>Notifications are collected and delivered at the times you choose. No 3 AM wake-ups. No interruption during deep work. You can set quiet hours, choose a daily digest, or turn off notifications entirely for specific conversation types.</p>\n<h2 id=\"your-timeline-your-pace\">Your timeline, your pace</h2>\n<p><strong>My Feed</strong> is chronological. It shows posts from accounts you follow without applying the For You ranking.</p>\n<p>The optional <strong>For You</strong> feed ranks eligible posts from the data available to the server and provides explanations and feedback controls. Behavioral learning has a separate consent setting; learned data belongs to the account, is not federated, and can be paused, reset or exported. The administrator controls whether ranked recommendations are available. It is a recommendation system, and its quality depends on local data, remote synchronization and the candidate posts available.</p>\n<h2 id=\"end-of-timeline-marker\">End-of-timeline marker</h2>\n<p>A subtle marker shows where you&#39;ve already read. This prevents doomscrolling — the mindless pull-to-refresh loop that consumes hours. When you reach the marker, you know you&#39;re caught up. You can stop.</p>\n<h2 id=\"ai-content-labeling\">AI content labeling</h2>\n<p>Settings includes a control for hiding posts that identify themselves as AI-generated. It depends on posts carrying the relevant label and cannot identify unlabeled AI content.</p>\n<h2 id=\"private-by-default\">Private by default</h2>\n<ul>\n<li>Your account can be private — new followers need your approval</li>\n<li>Photos lose their location data (EXIF, GPS) before they&#39;re stored or sent</li>\n<li>The app does not need a third-party map or GIF service and includes no advertising code. Federation and enabled integrations still exchange data with remote servers.</li>\n<li>The 881 built-in emoji are served from your own server</li>\n</ul>\n<h2 id=\"you-can-leave-anytime\">You can leave anytime</h2>\n<p>Your data is never locked in:</p>\n<ul>\n<li>Full export in standard format (Mastodon-compatible)</li>\n<li>Account move to another server, with automatic redirect for followers</li>\n<li>Import supported posts, follows and account data from the sources listed in the current <a href=\"/docs/moving\">migration guide</a></li>\n</ul>\n<h2 id=\"moderation-that-protects-people\">Moderation that protects people</h2>\n<ul>\n<li>Five graduated actions: warn, mark sensitive, silence, take down, suspend</li>\n<li>Every action names the moderator and is recorded in an audit log</li>\n<li>Domain blocks clean up what a blocked server already sent</li>\n<li>Reports about remote accounts are forwarded without exposing your identity</li>\n</ul>\n<h2 id=\"built-for-organisations-not-advertisers\">Built for organisations, not advertisers</h2>\n<p>Aloha Social runs on your organisation&#39;s Aloha. There&#39;s no ad server to feed, so nothing about your reading is measured on anyone&#39;s behalf. The login you already have — including SSO and 2FA — is the login. Your posts live next to your files, calendar, and chat, on infrastructure your organisation controls.</p>\n<h2 id=\"further-reading\">Further reading</h2>\n<ul>\n<li><a href=\"/protect\">How Aloha Social protects you</a> — the full list of safety and privacy features</li>\n<li><a href=\"/privacy\">Privacy policy</a> — what is stored, what leaves your server, and why</li>\n<li><a href=\"/rules\">Rules for using Aloha Social</a> — community guidelines and moderation</li>\n<li><a href=\"/why\">Why Aloha Social</a> — 30 reasons it&#39;s different</li>\n</ul>\n","toc":[{"id":"no-engagement-scoreboard","text":"No engagement scoreboard","level":2},{"id":"calm-notifications-by-default","text":"Calm notifications by default","level":2},{"id":"quiet-hours-and-digests","text":"Quiet hours and digests","level":2},{"id":"your-timeline-your-pace","text":"Your timeline, your pace","level":2},{"id":"end-of-timeline-marker","text":"End-of-timeline marker","level":2},{"id":"ai-content-labeling","text":"AI content labeling","level":2},{"id":"private-by-default","text":"Private by default","level":2},{"id":"you-can-leave-anytime","text":"You can leave anytime","level":2},{"id":"moderation-that-protects-people","text":"Moderation that protects people","level":2},{"id":"built-for-organisations-not-advertisers","text":"Built for organisations, not advertisers","level":2},{"id":"further-reading","text":"Further reading","level":2}]}];

export const SITE_PAGE_BY_PATH: Record<string, SitePage> = Object.fromEntries(
  SITE_PAGES.map((page) => [page.path, page]),
);
